static const char* extended(const char*op,cJSON*p){
 if(!strcmp(op,"batch")){if(currentUser.type!=TEACHER)return "无权导入";cJSON*rows=cJSON_GetObjectItem(p,"rows"),*r;if(!cJSON_IsArray(rows)||cJSON_GetArraySize(rows)<1||cJSON_GetArraySize(rows)>MAX_STUDENTS)return "导入行数无效";int seen[MAX_STUDENTS]={0},c=num(p,"classId");if(c<0||c>=classCount||classInactive[c])return "班级无效或已停用";cJSON_ArrayForEach(r,rows){int i=findStudentIndex(str(r,"id"));cJSON*v=cJSON_GetObjectItem(r,"score");if(i<0||!hasTeacherAccess(&students[i])||studentClass(students[i].stuNum)!=c||seen[i]++||courseIndex(&students[i],currentUser.teachCourse)>=0||students[i].courseCount>=MAX_COURSES||strcmp(str(r,"course"),currentUser.teachCourse)||(strlen(str(r,"name"))&&strcmp(str(r,"name"),students[i].name))||!cJSON_IsNumber(v)||!isfinite(v->valuedouble)||v->valuedouble<0||v->valuedouble>100)return "导入存在无效记录、重复记录、已有成绩或权限冲突，整批拒绝";}cJSON_ArrayForEach(r,rows){Student*s=&students[findStudentIndex(str(r,"id"))];int k=s->courseCount++;strcpy(s->courses[k].course,currentUser.teachCourse);s->courses[k].score=(float)cJSON_GetNumberValue(cJSON_GetObjectItem(r,"score"));}auditEvent("csv-import",currentUser.teachCourse);return saveAll()?NULL:"保存失败，已回滚";}
 if(currentUser.type!=ADMIN||!verifyPassword(str(p,"password"),currentUser.password))return "管理员密码错误或无权操作";
 if(!strcmp(op,"delete")){const char*id=str(p,"id");if(strcmp(str(p,"confirm"),id))return "确认文字不匹配";int s=findStudentIndex(id);if(s<0)return "学生不存在";removeClassMember(id);for(int i=s;i<studentCount-1;i++)students[i]=students[i+1];studentCount--;for(int u=0;u<userCount;u++)if(users[u].type==STUDENT&&!strcmp(users[u].username,id)){for(int k=u;k<userCount-1;k++){users[k]=users[k+1];strcpy(userDisplayNames[k],userDisplayNames[k+1]);}userCount--;break;}auditEvent("student-delete",id);return saveAll()?NULL:"保存失败";}
 if(!strcmp(op,"clear")){if(strcmp(str(p,"confirm"),"清空全部用户"))return "确认文字不匹配";users[0]=currentUser;userCount=1;studentCount=0;demoSeedVersion=0;memset(userDisplayNames,0,sizeof(userDisplayNames));for(int c=0;c<classCount;c++)schoolClasses[c].count=0;auditEvent("users-clear","web confirmed");return saveAll()?NULL:"保存失败";}
 return "未知操作";
}
